package net.officefloor.hq.app.person;

/** The body of a merge: the person on the sheet the merged person goes into. */
public record MergeRequest(Long intoId) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.RequestBody;

public class MergePerson {
    // Only a steward (a delegation included) merges a person, into another person on the sheet; neither may be retired.
    public void merge(@RequestBody(required = false) MergeRequest body, @Val Person person, People people,
            Settings settings, Sheets sheets, ServerHttpConnection connection, Out<MergedPerson> mergedOut,
            Out<PersonResponse> responseOut) throws PersonMergeRefusedException {
        if (!Settings.STEWARD.equals(settings.role(person.sheetId(), Audit.user(connection).trim()))) {
            throw new PersonMergeRefusedException("Only a steward can merge people.");
        }
        Person into = body == null || body.intoId() == null ? null : people.find(person.sheetId(), body.intoId());
        if (into == null) {
            throw new PersonMergeRefusedException("Choose a person on this sheet to merge into.");
        }
        if (into.id() == person.id()) {
            throw new PersonMergeRefusedException("A person cannot be merged into themselves.");
        }
        if (person.retired() || into.retired()) {
            throw new PersonMergeRefusedException("A retired person cannot be merged.");
        }
        people.merge(person.sheetId(), person.id(), into.id());
        mergedOut.set(new MergedPerson(person, into));
        responseOut.set(PersonResponse.from(people.find(person.sheetId(), into.id()), sheets.today(person.sheetId())));
    }
}
package net.officefloor.hq.app.person;

/** A merge done: the person merged ({@code from}, now gone from the sheet) and the person they went into. */
public record MergedPerson(Person from, Person into) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditPersonMerged {
    public void audit(@Val MergedPerson merged, ServerHttpConnection connection, Audit audit) {
        audit.record(Audit.line("PERSON_MERGED", merged.from().sheetId(), Audit.user(connection),
                "from=" + merged.from().name(), "into=" + merged.into().name()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandlePersonMergeRefused {
    public void handle(@Parameter PersonMergeRefusedException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.UNPROCESSABLE_ENTITY));
    }
}
package net.officefloor.hq.app.person;

/** A merge that may not happen: not a steward, the same person, no such person, or either of them retired. */
public class PersonMergeRefusedException extends Exception {

    public PersonMergeRefusedException(String message) {
        super(message);
    }
}
handle:
  class: net.officefloor.hq.app.person.HandlePersonMergeRefused
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { usePersonError } from './usePersonError';
import { useUser } from '../session/useUser';
import { peopleQuery } from './peopleQuery';
import type { Person } from './peopleQuery';
import { sheetKey } from '../sheet/sheetQuery';

/**
 * The control that merges the person into another (a steward only; neither may be retired). The merged person's
 * claims, aliases, patrons and pool memberships go to the other and they leave the list, so every figure of the
 * sheet is re-read.
 */
function PersonMerge({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [into, setInto] = useState('');
  const [, setError] = usePersonError(personId);
  const once = useSubmitOnce();
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const merge = useMutation({
    mutationFn: (intoId: number) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/merge`, { intoId }, user),
    onSuccess: async () => {
      setInto('');
      setError('');
      await queryClient.invalidateQueries({ queryKey: sheetKey(sheetId) });
    },
    onError: () => setError('The person could not be merged.'),
  });

  return (
    <td>
      <select
        data-testid="person-merge-into"
        value={into}
        onChange={(e) => {
          setInto(e.target.value);
          setError('');
        }}
      >
        <option value="">merge into…</option>
        {people.map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>{' '}
      <button
        type="button"
        data-testid="person-merge"
        disabled={merge.isPending}
        onClick={() => {
          setError('');
          if (into === '') {
            setError('Choose a person to merge into.');
            return;
          }
          once(() => merge.mutateAsync(Number(into)));
        }}
      >
        Merge
      </button>
    </td>
  );
}

// The row's `person-error` is shown by the hold cell, shared by every cell acting on the person.
export const contributions = [
  PersonHeaders.fill({ order: 23, Component: () => <th>Merge</th> }),
  PersonCells.fill({ order: 23, Component: PersonMerge }),
];

